  player.masterDisciple.swornBrothers.push({
    id: npc.id,
    name: npc.name,
    realm: npc.realm,
    portrait: npc.portrait,
    rank: player.masterDisciple.swornBrothers.length + 1,
    date: new Date().toISOString(),
  });
